  "r_rhyme_roka_0": {
    "text": "Róka fut a réten át.",
    "file": "audio/voice/r_rhyme_roka_0.mp3"
  },
  "r_rhyme_roka_1": {
    "text": "Robot őrzi a répát.",
    "file": "audio/voice/r_rhyme_roka_1.mp3"
  },
  "r_rhyme_roka_2": {
    "text": "Ropi roppan, perec kerek.",
    "file": "audio/voice/r_rhyme_roka_2.mp3"
  },
  "r_rhyme_roka_3": {
    "text": "Velük játszik minden gyerek.",
    "file": "audio/voice/r_rhyme_roka_3.mp3"
  },
  "r_rhyme_kert_0": {
    "text": "Piros rózsa nyílik reggel.",
    "file": "audio/voice/r_rhyme_kert_0.mp3"
  },
  "r_rhyme_kert_1": {
    "text": "Robot locsol friss vízcseppel.",
    "file": "audio/voice/r_rhyme_kert_1.mp3"
  },
  "r_rhyme_kert_2": {
    "text": "Róka körben táncot jár.",
    "file": "audio/voice/r_rhyme_kert_2.mp3"
  },
  "r_rhyme_kert_3": {
    "text": "Ránk egy szép virágkert vár.",
    "file": "audio/voice/r_rhyme_kert_3.mp3"
  },
  "r_rhyme_sator_0": {
    "text": "Erre gyere, erre várunk!",
    "file": "audio/voice/r_rhyme_sator_0.mp3"
  },
  "r_rhyme_sator_1": {
    "text": "Erdő mellett sátrat állunk.",
    "file": "audio/voice/r_rhyme_sator_1.mp3"
  },
  "r_rhyme_sator_2": {
    "text": "Körte kerül a kosárba.",
    "file": "audio/voice/r_rhyme_sator_2.mp3"
  },
  "r_rhyme_sator_3": {
    "text": "Róka indul vacsorára.",
    "file": "audio/voice/r_rhyme_sator_3.mp3"
  },
  "r_rhyme_robot_0": {
    "text": "Rajzol a robot: kerek a nap.",
    "file": "audio/voice/r_rhyme_robot_0.mp3"
  },
  "r_rhyme_robot_1": {
    "text": "Piros ceruzát a kezébe kap.",
    "file": "audio/voice/r_rhyme_robot_1.mp3"
  },
  "r_rhyme_robot_2": {
    "text": "Rajzol egy rókát, rajzol egy várat.",
    "file": "audio/voice/r_rhyme_robot_2.mp3"
  },
  "r_rhyme_robot_3": {
    "text": "Rajzol az égre repülő madarat.",
    "file": "audio/voice/r_rhyme_robot_3.mp3"
  },
  "r_mission_kirandulas": {
    "text": "Kirándulásra készülünk. Küldj ruhát és rollert!",
    "file": "audio/voice/r_mission_kirandulas.mp3"
  },
  "r_mission_ebed": {
    "text": "Ebédet készítünk. Küldj répát és rizst!",
    "file": "audio/voice/r_mission_ebed.mp3"
  },
  "r_mission_uzsonna": {
    "text": "Gyümölcsuzsonna készül. Küldj körtét és barackot!",
    "file": "audio/voice/r_mission_uzsonna.mp3"
  },
  "r_mission_unnep": {
    "text": "Ünnepi asztalt készítünk. Küldj tortát és virágot!",
    "file": "audio/voice/r_mission_unnep.mp3"
  },
  "r_mission_piknik": {
    "text": "Piknikre készülünk. Küldj poharat és kosarat!",
    "file": "audio/voice/r_mission_piknik.mp3"
  },
  "r_mission_tabor": {
    "text": "Tábort építünk. Küldj vödröt és sátrat!",
    "file": "audio/voice/r_mission_tabor.mp3"
  },
  "r_mission_kert": {
    "text": "Robot kertészkedik. Küldj robotot és répát!",
    "file": "audio/voice/r_mission_kert.mp3"
  },
  "r_mission_zene": {
    "text": "Zenés ünnep lesz. Küldj rádiót és rózsát!",
    "file": "audio/voice/r_mission_zene.mp3"
  },
  "r_mission_rajz": {
    "text": "Virágot rajzolunk. Küldj ceruzát és virágot!",
    "file": "audio/voice/r_mission_rajz.mp3"
  },
  "r_mission_suti": {
    "text": "Nyit a sütöde. Küldj perecet és tortát!",
    "file": "audio/voice/r_mission_suti.mp3"
  },
  "r_mission_gyujtes": {
    "text": "Gyűjtögetni indulunk. Küldj kosarat és vödröt!",
    "file": "audio/voice/r_mission_gyujtes.mp3"
  },
  "r_mission_vacsora": {
    "text": "Vacsora a sátornál. Küldj sátrat és poharat!",
    "file": "audio/voice/r_mission_vacsora.mp3"
  },
